(526777, 52568, 327, '<td valign="top">lol Freddies....you must be in the PNW. Hee hee. Good one.</td>', 'lol Freddies....you must be in the PNW. Hee hee. Good one.', '2003-12-31 00:06:01.000000', NULL, 1),
(526778, 52861, 12962, '<td valign="top">I think it''s fabulous, not tacky ...</td>', 'I think it''s fabulous, not tacky ...', '2003-12-31 00:06:19.000000', NULL, 1),
(526796, 52584, 6668, '<td valign="top">LOL That''s funny!</td>', 'LOL That''s funny!', '2003-12-31 00:22:10.000000', NULL, 1),
(526805, 52816, 14386, '<td valign="top">Nice cute angel but the frame is a bit overbearing.</td>', 'Nice cute angel but the frame is a bit overbearing.', '2003-12-31 00:31:05.000000', NULL, 1),
(526807, 52861, 6668, '<td valign="top">The blinds on the bottom half of the photo and the electric cord on the top are very distracting, would have been better on a solid background.</td>', 'The blinds on the bottom half of the photo and the electric cord on the top are very distracting, would have been better on a solid background.', '2003-12-31 00:34:03.000000', NULL, 1),
(526809, 52205, 14386, '<td valign="top">Not really tacky but extremely enjoyable picture. Composition is very good.</td>', 'Not really tacky but extremely enjoyable picture. Composition is very good.', '2003-12-31 00:34:23.000000', NULL, 1),
(526810, 52761, 3419, '<td valign="top">Very nicely framed and exposed. The light is very well captured without flaring - well done.</td>', 'Very nicely framed and exposed. The light is very well captured without flaring - well done.', '2003-12-31 00:34:32.000000', NULL, 1),
(526812, 52229, 6668, '<td valign="top">I think they''re kind of cute! :-)</td>', 'I think they''re kind of cute! :-)', '2003-12-31 00:35:02.000000', NULL, 1),
(526814, 52816, 6668, '<td valign="top">I like the colors of this shot, the border also works well with this one in my opinion. 9</td>', 'I like the colors of this shot, the border also works well with this one in my opinion. 9', '2003-12-31 00:37:01.000000', NULL, 1),
(526815, 52602, 14386, '<td valign="top">Wonderful colors.  Good, symmetrical composition.</td>', 'Wonderful colors.  Good, symmetrical composition.', '2003-12-31 00:38:30.000000', NULL, 1),
(526826, 52919, 11078, '<td valign="top">Never call sponge bob tacky! He is a wonderful sponge I love him to bits he makes me laugh! Good photo  though</td>', 'Never call sponge bob tacky! He is a wonderful sponge I love him to bits he makes me laugh! Good photo  though', '2003-12-31 00:47:39.000000', NULL, 1),
(526829, 52672, 6668, '<td valign="top">cute shot but it seems to have alot of noise in it.</td>', 'cute shot but it seems to have alot of noise in it.', '2003-12-31 00:50:08.000000', NULL, 1),
(526840, 52513, 2579, '<td valign="top">im kind of questioning what''s going in this picture......</td>', 'im kind of questioning what''s going in this picture......', '2003-12-31 01:01:33.000000', NULL, 1),
(526856, 52443, 9387, '<td valign="top">I don''t think this is tacky at all.</td>', 'I don''t think this is tacky at all.', '2003-12-31 01:29:54.000000', NULL, 1),
(526857, 52674, 9387, '<td valign="top">This may be overdone to your taste but I actually don''t think it looks all that bad.</td>', 'This may be overdone to your taste but I actually don''t think it looks all that bad.', '2003-12-31 01:32:12.000000', NULL, 1),
(526859, 52847, 12160, '<td valign="top">Very interesting angle. Something I find so tacky isn''t so anymore. Nicely done although I would have preferred more contrast. 7</td>', 'Very interesting angle. Something I find so tacky isn''t so anymore. Nicely done although I would have preferred more contrast. 7', '2003-12-31 01:35:46.000000', NULL, 1),
(526861, 52452, 10170, '<td valign="top">Good lighting on what I imagine was not an easy subject.</td>', 'Good lighting on what I imagine was not an easy subject.', '2003-12-31 01:47:31.000000', NULL, 1),
(526862, 52801, 10170, '<td valign="top">Very tacky indeed.  Nice chot.</td>', 'Very tacky indeed.  Nice chot.', '2003-12-31 01:51:59.000000', NULL, 1),
(526865, 52274, 10170, '<td valign="top">My god!  I now live in Australia, but there\''s no way on earth that is Morcome and Wise on the TV is it!!!  That could even be Dec O\''Connor episode *laugh*  Fun shot.</td>', 'My god!  I now live in Australia, but there\''s no way on earth that is Morcome and Wise on the TV is it!!!  That could even be Dec O\''Connor episode *laugh*  Fun shot.', '2003-12-31 01:53:54.000000', NULL, 1),
(526867, 52352, 10887, '<td valign="top">Tacky? Yep!</td>', 'Tacky? Yep!', '2003-12-31 02:00:22.000000', NULL, 1),
(526868, 52808, 10887, '<td valign="top">Ok...... and that tree is kinda tacky too I think.</td>', 'Ok...... and that tree is kinda tacky too I think.', '2003-12-31 02:01:56.000000', NULL, 1),
(526870, 52677, 10887, '<td valign="top">Nononono - this is not tacky! It´s cute! Love it anyway :-)</td>', 'Nononono - this is not tacky! It´s cute! Love it anyway :-)', '2003-12-31 02:02:48.000000', NULL, 1),
(526874, 52235, 10170, '<td valign="top">Wow, over done or what!  Good pic.</td>', 'Wow, over done or what!  Good pic.', '2003-12-31 02:14:11.000000', NULL, 1),
(526902, 52583, 12252, '<td valign="top">Love it. Wonder how many snaps it took (no pun) to get this pose. Perfect pose, great background. I like the frame as well. And yes -- VERY tacky ornaments! We have a winner here!</td>', 'Love it. Wonder how many snaps it took (no pun) to get this pose. Perfect pose, great background. I like the frame as well. And yes -- VERY tacky ornaments! We have a winner here!', '2003-12-31 03:06:56.000000', NULL, 1),
(526903, 52343, 12252, '<td valign="top">Looks perfectly hidious! Would have liked to see less light in the background. The "thing" to the right of his face is distracting.</td>', 'Looks perfectly hidious! Would have liked to see less light in the background. The "thing" to the right of his face is distracting.', '2003-12-31 03:08:04.000000', NULL, 1),
(526904, 52921, 12252, '<td valign="top">I don''t see what''s so tacky. The composition is a bit busy and yet spread out too much. Perhaps if you''d focused on just one ornament?</td>', 'I don''t see what''s so tacky. The composition is a bit busy and yet spread out too much. Perhaps if you''d focused on just one ornament?', '2003-12-31 03:09:53.000000', NULL, 1),
(526906, 52901, 12252, '<td valign="top">Granted, they didn''t do much decorating, so maybe that''s why you see it as tacky?</td>', 'Granted, they didn''t do much decorating, so maybe that''s why you see it as tacky?', '2003-12-31 03:10:58.000000', NULL, 1),
(526907, 52626, 12252, '<td valign="top">Ouch! Certainly fits the challenge! What is that -- a fish on the bottom? Not sure you needed all that brick to the right, perhaps crop closer.</td>', 'Ouch! Certainly fits the challenge! What is that -- a fish on the bottom? Not sure you needed all that brick to the right, perhaps crop closer.', '2003-12-31 03:12:08.000000', NULL, 1),
(526909, 52816, 12252, '<td valign="top">Technically okay, but I guess I don''t see the ornament as tacky. The black frame is too wide for my taste, but I do like the color border.</td>', 'Technically okay, but I guess I don''t see the ornament as tacky. The black frame is too wide for my taste, but I do like the color border.', '2003-12-31 03:13:26.000000', NULL, 1),
(526910, 52917, 12252, '<td valign="top">OMG...this is tacky! Good lighting except the bulb on the top left is distracting. Perhaps if there were more bulbs, or no bulbs. But what a pickle!</td>', 'OMG...this is tacky! Good lighting except the bulb on the top left is distracting. Perhaps if there were more bulbs, or no bulbs. But what a pickle!', '2003-12-31 03:14:24.000000', NULL, 1),
(526911, 52497, 12252, '<td valign="top">I can''t decide what''s going on here. Is that scotch tape on the top over the hat? Is the dog (?) bear (?) drinking from a flower vase? Is he sitting on a comode? I''m lost...</td>', 'I can''t decide what''s going on here. Is that scotch tape on the top over the hat? Is the dog (?) bear (?) drinking from a flower vase? Is he sitting on a comode? I''m lost...', '2003-12-31 03:16:49.000000', NULL, 1),
(526912, 52761, 12252, '<td valign="top">It''s tacky because the star is upside down, right? It is a rather gaudy star. Picture well done, and I really like how you framed it.</td>', 'It''s tacky because the star is upside down, right? It is a rather gaudy star. Picture well done, and I really like how you framed it.', '2003-12-31 03:18:07.000000', NULL, 1),
(526913, 52584, 12252, '<td valign="top">Good idea and execution but you don''t need the cigarette sticking up. It''s plenty tacky enough having Santa''s beard serving as an ashtray -- yuck! For me if you''d left that one cigarette out the image would have been more powerful and believable, because obviously the "Santa" isn''t really smoking, but some human being was, and used the ornament in a tacky way. Hope I''m making sense...</td>', 'Good idea and execution but you don''t need the cigarette sticking up. It''s plenty tacky enough having Santa''s beard serving as an ashtray -- yuck! For me if you''d left that one cigarette out the image would have been more powerful and believable, because obviously the "Santa" isn''t really smoking, but some human being was, and used the ornament in a tacky way. Hope I''m making sense...', '2003-12-31 03:20:18.000000', NULL, 1),
(526914, 52847, 12252, '<td valign="top">Cool picture, but I don''t see how this illustrates or captures "tackiness." I really like the capture, however... :-)</td>', 'Cool picture, but I don''t see how this illustrates or captures "tackiness." I really like the capture, however... :-)', '2003-12-31 03:21:09.000000', NULL, 1),
(526915, 52776, 12252, '<td valign="top">Yep, tacky alright! I wish the image was wider and taller -- in other words, not so tightly cropped. Notice I said cropped, not...oh, never mind. ;-)</td>', 'Yep, tacky alright! I wish the image was wider and taller -- in other words, not so tightly cropped. Notice I said cropped, not...oh, never mind. ;-)', '2003-12-31 03:22:27.000000', NULL, 1),
