(529369, 52771, 8005, '<td valign="top">This is Tacky?</td>', 'This is Tacky?', '2004-01-02 07:25:31.000000', NULL, 1),
(529377, 52743, 14614, '<td valign="top">The title says it all!  Too bad about the dark "lump" in the foreground.  DIdn''t want to hang on the fence - sacrifice life and limb? ;-)</td>', 'The title says it all!  Too bad about the dark "lump" in the foreground.  DIdn''t want to hang on the fence - sacrifice life and limb? ;-)', '2004-01-02 07:46:20.000000', NULL, 1),
(529388, 52352, 5158, '<td valign="top">LOL! Very creative! technically It cold have been improved by not using the flash but rather a lamp. But maybe that wasn''t possible! A 8 for me.</td>', 'LOL! Very creative! technically It cold have been improved by not using the flash but rather a lamp. But maybe that wasn''t possible! A 8 for me.', '2004-01-02 08:11:03.000000', NULL, 1),
(529389, 52820, 5158, '<td valign="top">Wonderfull colors! Something for a color-cahllenge.<br/>Nice perspective too. It does not fit the challenge too well, but it''s nice to see something different here.</td>', 'Wonderfull colors! Something for a color-cahllenge.Nice perspective too. It does not fit the challenge too well, but it''s nice to see something different here.', '2004-01-02 08:13:19.000000', NULL, 1),
(529391, 52295, 5158, '<td valign="top">Very creative! To sad that it''s so dark and fuzzy. Still a 7 for me.</td>', 'Very creative! To sad that it''s so dark and fuzzy. Still a 7 for me.', '2004-01-02 08:15:03.000000', NULL, 1),
(529393, 52841, 14453, '<td valign="top">Actually I think it''s not really tacky... And to present it in a very esthetic way makes it even less tacky... In fact I think you submitted a picture (and a good one, I like the contrast) with a lot of taste!!</td>', 'Actually I think it''s not really tacky... And to present it in a very esthetic way makes it even less tacky... In fact I think you submitted a picture (and a good one, I like the contrast) with a lot of taste!!', '2004-01-02 08:34:51.000000', NULL, 1),
(529394, 52855, 14453, '<td valign="top">It seems pretty tacky but from closer we would feel it better. Otherwise I like the composition with the curtains, it gives a theatrical feeling!</td>', 'It seems pretty tacky but from closer we would feel it better. Otherwise I like the composition with the curtains, it gives a theatrical feeling!', '2004-01-02 08:36:36.000000', NULL, 1),
(529396, 52407, 14453, '<td valign="top">Joyeux Noël!!!  That''s very tacky.... I would like to see it from a little bit closer, to see more details.</td>', 'Joyeux Noël!!!  That''s very tacky.... I would like to see it from a little bit closer, to see more details.', '2004-01-02 08:41:14.000000', NULL, 1),
(529398, 52443, 14453, '<td valign="top">It was said in the beginning of the challenge that what was tacky to you was maybe not for the others... I find this house very beautifull and it seems elegant to me!  Otherwise it is a good night picture, maybe a little far from your subject.</td>', 'It was said in the beginning of the challenge that what was tacky to you was maybe not for the others... I find this house very beautifull and it seems elegant to me!  Otherwise it is a good night picture, maybe a little far from your subject.', '2004-01-02 08:44:14.000000', NULL, 1),
(529400, 52858, 14453, '<td valign="top">Woooouuu!! Pretty tacky! And I can imagine what the result is at night, when they light it up!!!</td>', 'Woooouuu!! Pretty tacky! And I can imagine what the result is at night, when they light it up!!!', '2004-01-02 08:49:54.000000', NULL, 1),
(529402, 52216, 14448, '<td valign="top">Good shot.  I like the composition.  At first I thought Santa should be framed tighter, until I decided that I like how Santa appears to be flying out from among the clouds of artificial pine needles.  Subject seems slightly out of focus.</td>', 'Good shot.  I like the composition.  At first I thought Santa should be framed tighter, until I decided that I like how Santa appears to be flying out from among the clouds of artificial pine needles.  Subject seems slightly out of focus.', '2004-01-02 08:51:14.000000', NULL, 1),
(529403, 52674, 14453, '<td valign="top">I feel it''s a bit too far.  It appears a little bit fuzzy.</td>', 'I feel it''s a bit too far.  It appears a little bit fuzzy.', '2004-01-02 08:51:16.000000', NULL, 1),
(529404, 52849, 14453, '<td valign="top">not tacky!!</td>', 'not tacky!!', '2004-01-02 08:51:40.000000', NULL, 1),
