INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(531493, 52306, 6870, '<td valign="top">Clever title. What makes this are the eyes of the doll angel. Weird, fun, effective shot. 9</td>', 'Clever title. What makes this are the eyes of the doll angel. Weird, fun, effective shot. 9', '2004-01-04 16:13:30.000000', NULL, 1),
(531515, 52847, 9932, '<td valign="top">This is to nice to be tacky.</td>', 'This is to nice to be tacky.', '2004-01-04 17:08:56.000000', NULL, 1),
(531529, 52352, 14448, '<td valign="top">Funny and tacky - at least from this angle!  The foreground branches on the right, and the wiring and rod on the ground are distracting.</td>', 'Funny and tacky - at least from this angle!  The foreground branches on the right, and the wiring and rod on the ground are distracting.', '2004-01-04 17:40:27.000000', NULL, 1),
(531545, 52917, 2158, '<td valign="top">I love it!</td>', 'I love it!', '2004-01-04 18:38:27.000000', NULL, 1),
(531563, 52352, 2553, '<td valign="top">This is so tacky that I had to send links to it to my husband at his work email so he could share with the guys in his office!  I don''t even care if you set this up just for the challenge; it is tacky, tacky, tacky!  LOL!</td>', 'This is so tacky that I had to send links to it to my husband at his work email so he could share with the guys in his office!  I don''t even care if you set this up just for the challenge; it is tacky, tacky, tacky!  LOL!', '2004-01-04 19:00:47.000000', NULL, 1),
(531564, 52269, 12906, '<td valign="top">Great shot. It fits the challenge perfectly!</td>', 'Great shot. It fits the challenge perfectly!', '2004-01-04 19:01:42.000000', NULL, 1),
(531567, 52653, 2553, '<td valign="top">My husband and I agree on this - ding,ding,ding;  we have a winner!!!  This is the tackiest thing we have ever seen!  We have a guy near us that we thought was tacky, but this takes the ribbon!  Great job shooting this too - very crisp and clear and you can see darned near every single light.  I never could get one this sharp.  Good Luck!</td>', 'My husband and I agree on this - ding,ding,ding;  we have a winner!!!  This is the tackiest thing we have ever seen!  We have a guy near us that we thought was tacky, but this takes the ribbon!  Great job shooting this too - very crisp and clear and you can see darned near every single light.  I never could get one this sharp.  Good Luck!', '2004-01-04 19:07:14.000000', NULL, 1),
